contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient) public payable {
        require(true);

        bool success1;
        try c.getFirstWithdrawalBonus(recipient) {
            success1 = true;
        } catch {
            success1 = false;
        }

        bool success2;
        try c.getFirstWithdrawalBonus(recipient) {
            success2 = true;
        } catch {
            success2 = false;
        }

        // At most one of the two calls may succeed: the bonus can be
        // claimed at most once per recipient.
        assert(!success1 || !success2);
    }

    receive() external payable {}
}

