contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address payable recipient) public payable {
        require(recipient == address(this));

        uint thisBefore = address(this).balance;
        uint cBefore = address(c).balance;

        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint thisAfter = address(this).balance;
        uint cAfter = address(c).balance;

        assert(
