contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address payable recipient) public payable {
        require(recipient == address(this));

        // First attempt: recipient is c itself, which cannot accept Ether,
        // so the inner reward transfer fails and the whole call reverts.
        bool reverted1;
        try c.getFirstWithdrawalBonus(payable(address(c))) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }

        uint before = address(this).balance;

        // Retry for a recipient that accepts Ether.
        bool reverted2;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        uint afterB = address(this).balance;

        assert(reverted1 && !reverted2 && afterB - before == 100);
    }

    receive() external payable {}
}

