contract InvMutTest {
    C c;
    uint reentrancyReverted;

    constructor(C _c) { c = _c; }

    function run(address payable recipient) public payable {
        require(recipient == address(this));
        c.getFirstWithdrawalBonus(recipient);
        assert(reentrancyReverted == 1);
    }

    receive() external payable {
        bool ok;
        try c.withdrawReward(address(this)) {
            ok = true;
        } catch {
            ok = false;
        }
        if (!ok) {
            reentrancyReverted = 1;
        }
    }
}

