        c.getFirstWithdrawalBonus(recipient);
        bool lockedAfterSuccess = c._locked();

        try c.getFirstWithdrawalBonus(address(c)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool lockedAfterFailure = c._locked();

        assert(!lockedAfterSuccess && !lockedAfterFailure && reverted);
    }

