contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address payable recipient) public payable {
        require(recipient != address(c));
        require(recipient != address(this));

        // Bonus payout for an arbitrary external recipient.
        c.getFirstWithdrawalBonus(recipient);

        // Bonus payout for a different recipient (this test contract, which accepts Ether).
        c.getFirstWithdrawalBonus(address(this));

        bool unlocked = !c._locked();
        assert(recipient.balance == 100 && address(this).balance == 100 && unlocked);
    }

    receive() external payable {
    }
}

contract InvMutTest {
    C c;
    address other;
    bool nestedReverted = true;

    constructor(C _c) { c = _c; }

    function run(address recipient) public payable {
        require(recipient != address(this));
        other = recipient;
        // rewardsForA[this] is 0, so withdrawReward sends 0 wei and invokes receive()
        c.withdrawReward(address(this));
        assert(nestedReverted);
    }

    receive() external payable {
        // Re-entrant call while the lock is held: must revert.
        try c.withdrawReward(other) {
            nestedReverted = false;
        } catch {
            nestedReverted = true;
        }
    }
}

